"use client";

import { useMemo, useState } from "react";
import { apiPost } from "../lib/api";

type ForecastResp = {
  method: "ml" | "arima";
  horizon: number;
  forecast: number[];
  low: number[];
  high: number[];
  vol_est: number;
  last_price: number;
};

type BSResp = {
  price: number;
  greeks: {
    delta: number;
    gamma: number;
    vega: number;
    theta: number;
    rho: number;
  };
};

type IVResp = { implied_vol: number };

type HestonResp = { price: number; method: string; steps: number; sims: number };

type MCResp = {
  S0: number;
  terminal_mean: number;
  terminal_p05: number;
  terminal_p95: number;
  payoff_mean?: number;
  payoff_p95?: number;
};

export default function Home() {
  // Example historical prices (you can later replace with CSV upload / real API)
  const [pricesText, setPricesText] = useState(
    "100,101,102,101,103,104,105,106,108,107,109,110,111,112,113,114,113,115,116,118,117,119,120,121,122,121,123,124,125,126,127,128,129,130"
  );

  const prices = useMemo(() => {
    return pricesText
      .split(",")
      .map((x) => Number.parseFloat(x.trim()))
      .filter((x) => Number.isFinite(x));
  }, [pricesText]);

  const [method, setMethod] = useState<"ml" | "arima">("ml");
  const [horizon, setHorizon] = useState<number>(5);

  const [S, setS] = useState<number>(130);
  const [K, setK] = useState<number>(130);
  const [T, setT] = useState<number>(1);
  const [r, setR] = useState<number>(0.03);
  const [sigma, setSigma] = useState<number>(0.25);
  const [type, setType] = useState<"call" | "put">("call");

  const [forecast, setForecast] = useState<ForecastResp | null>(null);
  const [bs, setBs] = useState<BSResp | null>(null);
  const [iv, setIv] = useState<IVResp | null>(null);
  const [heston, setHeston] = useState<HestonResp | null>(null);
  const [mc, setMc] = useState<MCResp | null>(null);

  const [busy, setBusy] = useState<string>("");
  const [err, setErr] = useState<string>("");

  const canForecast = prices.length >= 30;

  async function runForecast() {
    setErr("");
    setBusy("forecast");
    try {
      const data = await apiPost<ForecastResp>("/forecast", {
        prices,
        horizon,
        method,
      });
      setForecast(data);

      // Optional: set spot to first forecast point for forward-looking pricing
      if (data.forecast?.length) {
        setS(Number(data.forecast[0].toFixed(6)));
      }
    } catch (e: any) {
      setErr(String(e?.message || e));
    } finally {
      setBusy("");
    }
  }

  async function priceBS() {
    setErr("");
    setBusy("bs");
    try {
      const data = await apiPost<BSResp>("/pricing/black_scholes", {
        S,
        K,
        T,
        r,
        sigma,
        type,
      });
      setBs(data);
    } catch (e: any) {
      setErr(String(e?.message || e));
    } finally {
      setBusy("");
    }
  }

  async function solveIV() {
    setErr("");
    setBusy("iv");
    try {
      const target = bs?.price ?? 10;
      const data = await apiPost<IVResp>("/pricing/implied_vol", {
        price: target,
        S,
        K,
        T,
        r,
        type,
      });
      setIv(data);
      if (Number.isFinite(data.implied_vol)) setSigma(Number(data.implied_vol.toFixed(6)));
    } catch (e: any) {
      setErr(String(e?.message || e));
    } finally {
      setBusy("");
    }
  }

  async function priceHeston() {
    setErr("");
    setBusy("heston");
    try {
      // Backend endpoint prices a CALL under Heston MC
      const data = await apiPost<HestonResp>("/pricing/heston_call", {
        S,
        K,
        T,
        r,
        v0: sigma ** 2,
        kappa: 2.0,
        theta: sigma ** 2,
        vol_of_vol: 0.5,
        rho: -0.7,
        steps: 252,
        sims: 20000,
      });
      setHeston(data);
    } catch (e: any) {
      setErr(String(e?.message || e));
    } finally {
      setBusy("");
    }
  }

  async function runMC() {
    setErr("");
    setBusy("mc");
    try {
      const data = await apiPost<MCResp>("/sim/gbm_paths", {
        S0: S,
        mu: 0.10,
        sigma,
        T,
        steps: 252,
        sims: 20000,
        K,
      });
      setMc(data);
    } catch (e: any) {
      setErr(String(e?.message || e));
    } finally {
      setBusy("");
    }
  }

  return (
    <main style={{ padding: 24, fontFamily: "system-ui, -apple-system, Arial" }}>
      <h1 style={{ marginBottom: 6 }}>Quant Suite: Forecast + Pricing + Risk</h1>
      <p style={{ marginTop: 0, color: "#555" }}>
        Next.js (TypeScript) UI calling your Python FastAPI quant engine on{" "}
        <code>localhost:8000</code>.
      </p>

      {err && (
        <div
          style={{
            background: "#fee",
            border: "1px solid #f99",
            padding: 12,
            marginBottom: 12,
            borderRadius: 10,
          }}
        >
          <b>Error:</b> {err}
          <div style={{ marginTop: 6, color: "#555" }}>
            Common fix: ensure backend is running and <code>.env.local</code> has{" "}
            <code>NEXT_PUBLIC_API_BASE=http://localhost:8000</code> (then restart
            Next).
          </div>
        </div>
      )}

      <section
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: 16,
        }}
      >
        {/* Forecasting */}
        <div style={{ border: "1px solid #ddd", borderRadius: 12, padding: 16 }}>
          <h2 style={{ marginTop: 0 }}>Forecasting</h2>

          <label style={{ display: "block", fontWeight: 600 }}>
            Prices (comma-separated)
          </label>
          <textarea
            value={pricesText}
            onChange={(e) => setPricesText(e.target.value)}
            rows={6}
            style={{ width: "100%", marginTop: 6 }}
          />

          {!canForecast && (
            <div style={{ marginTop: 8, color: "#a00" }}>
              Need at least 30 prices (you have {prices.length}).
            </div>
          )}

          <div style={{ display: "flex", gap: 10, marginTop: 10, flexWrap: "wrap" }}>
            <label>
              Method{" "}
              <select
                value={method}
                onChange={(e) => setMethod(e.target.value as "ml" | "arima")}
              >
                <option value="ml">ML (Lag + Ridge)</option>
                <option value="arima">ARIMA</option>
              </select>
            </label>

            <label>
              Horizon{" "}
              <input
                type="number"
                min={1}
                max={60}
                value={horizon}
                onChange={(e) => setHorizon(Number(e.target.value))}
                style={{ width: 90 }}
              />
            </label>

            <button onClick={runForecast} disabled={!canForecast || busy !== ""}>
              {busy === "forecast" ? "Running..." : "Run forecast"}
            </button>
          </div>

          {forecast && (
            <div style={{ marginTop: 12 }}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                <div style={{ background: "#f7f7f7", padding: 10, borderRadius: 10 }}>
                  <div style={{ fontSize: 12, color: "#666" }}>Last price</div>
                  <div style={{ fontSize: 20, fontWeight: 700 }}>{forecast.last_price.toFixed(4)}</div>
                </div>
                <div style={{ background: "#f7f7f7", padding: 10, borderRadius: 10 }}>
                  <div style={{ fontSize: 12, color: "#666" }}>Vol estimate (log-return std)</div>
                  <div style={{ fontSize: 20, fontWeight: 700 }}>{forecast.vol_est.toFixed(6)}</div>
                </div>
              </div>

              <pre
                style={{
                  background: "#f7f7f7",
                  padding: 12,
                  borderRadius: 10,
                  marginTop: 10,
                  overflowX: "auto",
                }}
              >
{JSON.stringify(forecast, null, 2)}
              </pre>
            </div>
          )}
        </div>

        {/* Pricing */}
        <div style={{ border: "1px solid #ddd", borderRadius: 12, padding: 16 }}>
          <h2 style={{ marginTop: 0 }}>Option Pricing</h2>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 10 }}>
            <label>
              Spot S
              <input type="number" value={S} onChange={(e) => setS(Number(e.target.value))} />
            </label>
            <label>
              Strike K
              <input type="number" value={K} onChange={(e) => setK(Number(e.target.value))} />
            </label>
            <label>
              Time T (years)
              <input type="number" step="0.01" value={T} onChange={(e) => setT(Number(e.target.value))} />
            </label>
            <label>
              Rate r
              <input type="number" step="0.001" value={r} onChange={(e) => setR(Number(e.target.value))} />
            </label>
            <label>
              Vol sigma
              <input type="number" step="0.01" value={sigma} onChange={(e) => setSigma(Number(e.target.value))} />
            </label>
            <label>
              Type
              <select value={type} onChange={(e) => setType(e.target.value as "call" | "put")}>
                <option value="call">Call</option>
                <option value="put">Put</option>
              </select>
            </label>
          </div>

          <div style={{ display: "flex", gap: 8, marginTop: 12, flexWrap: "wrap" }}>
            <button onClick={priceBS} disabled={busy !== ""}>
              {busy === "bs" ? "Pricing..." : "Black-Scholes + Greeks"}
            </button>
            <button onClick={solveIV} disabled={busy !== ""}>
              {busy === "iv" ? "Solving..." : "Implied Vol (solve)"}
            </button>
            <button onClick={priceHeston} disabled={busy !== "" || type !== "call"}>
              {busy === "heston" ? "Running..." : "Heston (MC) [Call]"}
            </button>
            <button onClick={runMC} disabled={busy !== ""}>
              {busy === "mc" ? "Simulating..." : "GBM Monte Carlo (summary)"}
            </button>
          </div>

          {type !== "call" && (
            <div style={{ marginTop: 8, color: "#666" }}>
              Note: Heston endpoint is implemented for CALL in the backend example.
            </div>
          )}

          {bs && (
            <>
              <h3 style={{ marginBottom: 6 }}>Black-Scholes</h3>
              <pre style={{ background: "#f7f7f7", padding: 12, borderRadius: 10, overflowX: "auto" }}>
{JSON.stringify(bs, null, 2)}
              </pre>
            </>
          )}

          {iv && (
            <>
              <h3 style={{ marginBottom: 6 }}>Implied Vol</h3>
              <pre style={{ background: "#f7f7f7", padding: 12, borderRadius: 10, overflowX: "auto" }}>
{JSON.stringify(iv, null, 2)}
              </pre>
            </>
          )}

          {heston && (
            <>
              <h3 style={{ marginBottom: 6 }}>Heston (Monte Carlo)</h3>
              <pre style={{ background: "#f7f7f7", padding: 12, borderRadius: 10, overflowX: "auto" }}>
{JSON.stringify(heston, null, 2)}
              </pre>
            </>
          )}

          {mc && (
            <>
              <h3 style={{ marginBottom: 6 }}>GBM Monte Carlo Summary</h3>
              <pre style={{ background: "#f7f7f7", padding: 12, borderRadius: 10, overflowX: "auto" }}>
{JSON.stringify(mc, null, 2)}
              </pre>
            </>
          )}
        </div>
      </section>

      <footer style={{ marginTop: 18, color: "#777", fontSize: 13 }}>
        <div>
          Backend: <code>uvicorn app.main:app --reload --port 8000</code>
        </div>
        <div>
          Frontend: <code>npm run dev</code> (this page)
        </div>
      </footer>
    </main>
  );
}
